import AlchemystAI from '@alchemystai/sdk';
import * as fs from 'fs';

async function run() {
  const runId = process.env.ZEALT_RUN_ID;
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;

  if (!runId || !apiKey) {
    console.error('Missing environment variables ZEALT_RUN_ID or ALCHEMYST_AI_API_KEY');
    process.exit(1);
  }

  const client = new AlchemystAI({
    apiKey: apiKey,
  });

  // Document 1
  await client.v1.context.add({
    context_type: 'resource',
    source: 'docs',
    scope: 'internal',
    documents: [
      {
        content: 'The v1 engine uses a monolithic architecture.',
      },
    ],
    metadata: {
      fileName: `doc1-${runId}.txt`,
      groupName: ['eng', 'v1'],
    },
  });

  // Document 2
  await client.v1.context.add({
    context_type: 'resource',
    source: 'docs',
    scope: 'internal',
    documents: [
      {
        content: 'The v2 engine uses a microservices architecture.',
      },
    ],
    metadata: {
      fileName: `doc2-${runId}.txt`,
      groupName: ['eng', 'v2'],
    },
  });

  // Perform search
  // The hint suggests search might use different casing for metadata fields.
  // We want to filter for both 'eng' and 'v2'.
  const searchResponse = await client.v1.context.search({
    query: 'What architecture is used?',
    minimum_similarity_threshold: 0.1,
    similarity_threshold: 0.1,
    body_metadata: {
      group_name: ['eng', 'v2'],
    },
    scope: 'internal',
  });

  const contexts = searchResponse.contexts || [];
  if (contexts.length > 0) {
    const topResult = contexts[0].content;
    fs.writeFileSync('/home/user/myproject/output.log', `Result: ${topResult}`);
    console.log('Successfully wrote result to output.log');
  } else {
    console.log('No search results found');
  }
}

run().catch((err) => {
  console.error('Error occurred:', err);
  process.exit(1);
});

